#!/usr/bin/env node
// Builds the site exactly as a release would, but with a PROVISIONAL (loopback-only) default profile for the browser
// tests (test/site-default-independence.test.mjs). The profile is generated by scripts/network/default-profile.mjs from:
//   - the REAL reviewed authority profile (contracts/deployments/network-profile-base.json, digest checked) and the real
//     host contract pins: the tests run on an anvil fork of Base, which holds exactly those contracts;
//   - the REAL service index pin (contracts/deployments/service-index-pin-base.json);
//   - three loopback RPC proxies on FIXED ports (the profile is baked into the bundle);
//   - a fixture storage plan and host-policy mirror at public-looking names the test routes to local handlers.
// Then scripts/build-site.mjs --default-profile <module> --provisional-ok writes site/dist. Prints a JSON summary.
//   node test/helpers/default-site-fixture.mjs [--out-dir DIR]
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
export const PROXY_PORTS = [39651, 39652, 39653];
export const FIXTURE_STORAGE = { version: 1, minimumCopies: 2, replicas: [
  { upload: "https://s1.storage-a.net/add-json", audience: "0x" + "a1".repeat(32), gateway: "https://s1.storage-a.net/ipfs" },
  { upload: "https://s2.storage-b.net/add-json", audience: "0x" + "b2".repeat(32), gateway: "https://s2.storage-b.net/ipfs" }] };
export const POLICY_MIRROR = "https://policies.operator-c.net";
export const AUTHORITY = path.join(ROOT, "contracts/deployments/network-profile-base.json");
export const AUTHORITY_DIGEST = "sha256:" + createHash("sha256").update(fs.readFileSync(AUTHORITY)).digest("hex");

export function buildFixtureSite({ outDir = fs.mkdtempSync(path.join(os.tmpdir(), "default-site-")) } = {}){
  const storage = path.join(outDir, "storage-plan.json");
  fs.writeFileSync(storage, JSON.stringify(FIXTURE_STORAGE));
  const prof = path.join(outDir, "profile");
  const run = (args) => execFileSync("node", args, { cwd: ROOT, stdio: ["ignore", "pipe", "inherit"] }).toString().trim().split("\n").pop();
  const gen = JSON.parse(run([path.join(ROOT, "scripts/network/default-profile.mjs"), "generate", "--provisional", "--authority", AUTHORITY,
    "--expect-digest", AUTHORITY_DIGEST, "--expect-pins", path.join(ROOT, "contracts/deployments/contract-pins-base.json"),
    "--service-index-pin", path.join(ROOT, "contracts/deployments/service-index-pin-base.json"),
    ...PROXY_PORTS.flatMap((p) => ["--rpc", "http://127.0.0.1:" + p]), "--quorum", "2", "--confirmations", "0", "--max-block-age", "3600",
    "--storage-plan", storage, "--host-policy-origin", POLICY_MIRROR, "--name", "Base fork · provisional test default", "--out-dir", prof]));
  const mod = path.join(outDir, "default-profile.module.js");
  run([path.join(ROOT, "scripts/network/default-profile.mjs"), "module", "--dir", prof, "--provisional", "--out", mod]);
  // the build regenerates two tracked files in place (Tailwind's site/css/site.css, the contract artifacts module); they are
  // restored afterwards so building never changes the candidate's sources, and whether they differed is reported
  const regenerated = ["site/css/site.css", "site/js/gen/contract-artifacts.js"].map((f) => ({ f, before: fs.readFileSync(path.join(ROOT, f)) }));
  try { execFileSync("node", [path.join(ROOT, "scripts/build-site.mjs"), "--default-profile", mod, "--provisional-ok"], { cwd: ROOT, stdio: ["ignore", "ignore", "inherit"] }); }
  finally { for (const r of regenerated){ r.differed = Buffer.compare(fs.readFileSync(path.join(ROOT, r.f)), r.before) !== 0; fs.writeFileSync(path.join(ROOT, r.f), r.before); } }
  const dist = path.join(ROOT, "site/dist");
  const meta = JSON.parse(fs.readFileSync(path.join(dist, "default-profile.json"), "utf8"));
  if (meta.profileDigest !== gen.profileDigest) throw new Error("the built site carries another profile");
  const files = []; const walk = (d) => { for (const e of fs.readdirSync(d, { withFileTypes: true })){ const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else files.push(p); } };
  walk(dist); files.sort();
  const h = createHash("sha256"); for (const f of files){ h.update(path.relative(dist, f) + "\0"); h.update(fs.readFileSync(f)); }
  const summary = { outDir, dist, regeneratedDiffered: regenerated.filter((r) => r.differed).map((r) => r.f), profileDigest: gen.profileDigest, authorityDigest: gen.authorityDigest, distDigest: "sha256:" + h.digest("hex"), distFiles: files.length,
    profileText: fs.readFileSync(path.join(prof, "profile.json"), "utf8") };
  fs.writeFileSync(path.join(outDir, "summary.json"), JSON.stringify(summary, null, 2));
  return summary;
}

if (import.meta.url === `file://${process.argv[1]}`){
  const i = process.argv.indexOf("--out-dir");
  const outDir = i > 0 ? process.argv[i + 1] : undefined;
  if (outDir) fs.mkdirSync(outDir, { recursive: true });
  const s = buildFixtureSite(outDir ? { outDir } : {});
  console.log(JSON.stringify({ ...s, profileText: undefined }));
}
